<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api,session} from './api';
interface Matrix{revision:number;roles:{role:string;permissions:string[]}[]}
interface Definition{id:string;name:string;group:string;administratorOnly:boolean}
const definitions=ref<Definition[]>([]),matrix=ref<Matrix|null>(null),busy=ref(false),error=ref(''),message=ref(''),dirty=ref(false);
const roles:Record<string,string>={Administrator:'管理员',Operator:'操作员',Viewer:'浏览员'};
async function load(){const data=await api<{definitions:Definition[];matrix:Matrix}>('/api/permissions');definitions.value=data.definitions;matrix.value=data.matrix;dirty.value=false}
function checked(role:string,id:string){return !!matrix.value?.roles.find(g=>g.role===role)?.permissions.includes(id)}
function toggle(role:string,id:string,event:Event){const grant=matrix.value?.roles.find(g=>g.role===role);if(!grant)return;const value=(event.target as HTMLInputElement).checked;grant.permissions=grant.permissions.filter(p=>p!==id);if(value)grant.permissions.push(id);if(value&&['InstrumentControl','AverageTemperatureStart','RemoteLevelAdjust'].includes(id)&&!grant.permissions.includes('InstrumentStop'))grant.permissions.push('InstrumentStop');if(!value&&id==='InstrumentStop')grant.permissions=grant.permissions.filter(p=>!['InstrumentControl','AverageTemperatureStart','RemoteLevelAdjust'].includes(p));dirty.value=true;message.value=''}
async function save(){busy.value=true;error.value='';try{matrix.value=await api('/api/permissions','PUT',matrix.value);await session();dirty.value=false;message.value='岗位权限已保存。所有已登录账号的后续请求立即按新权限校验；原定时测温授权须重新编辑确认。'}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>void load().catch(e=>error.value=String(e)));
</script>
<template><section class="panel panel-body role-permissions"><div class="toolbar"><div><h2>岗位权限矩阵</h2><p class="help">勾选岗位允许执行的功能。实时监控可查看，历史查询与各项操作分别授权。</p></div><div class="inline-actions"><button class="button" :disabled="busy" @click="load().catch(e=>error=String(e))">重新载入</button><button class="button primary" :disabled="busy||!dirty" @click="save">保存岗位权限</button></div></div><p v-if="error" class="error-message" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><div class="table-wrap"><table><thead><tr><th>功能</th><th v-for="(name,role) in roles" :key="role">{{name}}</th></tr></thead><tbody><tr v-for="definition in definitions" :key="definition.id"><td><strong>{{definition.name}}</strong><small>{{definition.group}}</small></td><td v-for="(name,role) in roles" :key="role"><label class="permission-check"><input type="checkbox" :aria-label="name+' '+definition.name" :checked="checked(role,definition.id)" :disabled="busy||definition.administratorOnly" @change="toggle(role,definition.id,$event)"><span v-if="definition.administratorOnly">{{role==='Administrator'?'保留':'—'}}</span></label></td></tr></tbody></table></div><p class="help">允许仪表操作或平均测温时同步保留停止权限。账号、岗位权限、供方授权及业务恢复核查由管理员保留。修改权限后，原定时测温任务须重新编辑确认授权。岗位权限不能开放未交付模块，也不能超出本罐允许操作与设备支持范围；已执行任务仍保留必要收尾。</p></section></template>
